// Verificacao do idToken via Identity Toolkit accounts:lookup (apiKey PUBLICA do projeto).
// A resposta so retorna users[] se o idToken foi assinado pelo projeto e ainda e valido.
// Autorizacao = email == dona. NAO ecoa nem loga o token da SuperFrete (nem passa por aqui).
const OWNER = 'useaura@gmail.com';
const r = $input.first().json;
let ok = false, email = null, emailVerified = null, localId = null;
if (r && r.statusCode === 200 && r.body && Array.isArray(r.body.users) && r.body.users[0]) {
  const u = r.body.users[0];
  email = u.email || null;
  emailVerified = (u.emailVerified === true);
  localId = u.localId || null;
  if (email === OWNER && localId) ok = true; // emailVerified nao exigido: cadastro publico desativado no console (a dona e a unica conta)
}
return [{ json: { ok, email, emailVerified, localId } }];

// A1 - monta o PATCH do cofre gravando SO os campos presentes no body (token e/ou remetente).
// remetente e gravado como stringValue JSON (JSON.stringify) - facil de ler/parsear depois no Fluxo 3.
// updateMask so nos campos presentes: gravar so remetente NAO apaga o token, e vice-versa. Nada e ecoado.
const b = $('Webhook SF Token').first().json.body || {};
const hasToken = typeof b.token === 'string' && b.token.length > 0;
const rem = b.remetente;
const hasRem = rem && typeof rem === 'object' && !Array.isArray(rem) && Object.keys(rem).length > 0;
if (!hasToken && !hasRem) return [{ json: { valid: false, hadToken: hasToken } }];
const fields = { updatedAt: { integerValue: String(Date.now()) } };
const masks = ['updatedAt'];
if (hasToken) { fields.token = { stringValue: String(b.token) }; masks.push('token'); }
if (hasRem) { fields.remetente = { stringValue: JSON.stringify(rem) }; masks.push('remetente'); }
const query = masks.map(function (m) { return 'updateMask.fieldPaths=' + m; }).join('&');
return [{ json: { valid: true, hadToken: hasToken, body: { fields: fields }, query: query } }];

// FLUXO 2 - monta o package SERVER-SIDE e valida. O browser envia so {to_cep, itens:[{id,qtd}]}.
// Token: le do cofre (SA) mas NUNCA emite o valor daqui (o no HTTP le o token por expressao direto do no de leitura).
const wb = $('Webhook SF Cotar').first().json.body || {};
const to_cep = String(wb.to_cep == null ? '' : wb.to_cep).replace(/\D/g, '');
const itens = Array.isArray(wb.itens) ? wb.itens : [];
// --- token presente? (so booleano, sem expor) ---
const tokResp = $('Ler Token Cofre (Cotar)').first().json;
let hasToken = false;
if (tokResp && tokResp.statusCode === 200 && tokResp.body && tokResp.body.fields && tokResp.body.fields.token && typeof tokResp.body.fields.token.stringValue === 'string' && tokResp.body.fields.token.stringValue.length > 0) hasToken = true;
if (!hasToken) return [{ json: { valid: false, code: 400, motivo: 'sem token' } }];
// --- config/store: catalogo + FRETE.superfrete ---
const cfgResp = $('Ler Config Store (Cotar)').first().json;
let store = null;
if (cfgResp && cfgResp.statusCode === 200 && cfgResp.body && cfgResp.body.fields && cfgResp.body.fields.payload && typeof cfgResp.body.fields.payload.stringValue === 'string') {
  try { store = JSON.parse(cfgResp.body.fields.payload.stringValue); } catch (e) { store = null; }
}
const produtos = store && store.produtos;
const frete = (store && store.frete) || {};
const sf = frete.superfrete || {};
if (!Array.isArray(produtos) || produtos.length === 0) return [{ json: { valid: false, code: 400, motivo: 'catalogo indisponivel' } }];
if (!sf.origemCep) return [{ json: { valid: false, code: 400, motivo: 'origem nao configurada' } }];
if (to_cep.length !== 8) return [{ json: { valid: false, code: 400, motivo: 'cep destino invalido' } }];
const servicos = String(sf.servicos || '1,2,17');
const categorias = sf.categorias || {};
const DEFAULT = { weight: 0.3, height: 4, width: 12, length: 17 };
const mapa = {};
for (const p of produtos) mapa[String(p.id)] = p;
// HEURISTICA DE EMPACOTAMENTO (documentada no README - facil de trocar aqui):
// weight = Soma(peso*qtd); height = Soma(altura*qtd); width = max(largura); length = max(comprimento).
let W = 0, H = 0, Wd = 0, L = 0, itensOk = false;
for (const it of itens) {
  const prod = mapa[String(it && it.id)];
  const qtd = parseInt(it && it.qtd, 10);
  if (!prod || !Number.isInteger(qtd) || qtd <= 0) continue;
  let pk = prod.frete; // pacote por produto
  if (!pk) { const cat = prod.categoria; pk = (cat && categorias[cat]) ? categorias[cat] : null; } // por categoria
  if (!pk) pk = DEFAULT; // fallback
  const w = Number(pk.weight) || DEFAULT.weight;
  const h = Number(pk.height) || DEFAULT.height;
  const wd = Number(pk.width) || DEFAULT.width;
  const l = Number(pk.length) || DEFAULT.length;
  W += w * qtd; H += h * qtd; Wd = Math.max(Wd, wd); L = Math.max(L, l); itensOk = true;
}
if (!itensOk) return [{ json: { valid: false, code: 400, motivo: 'itens invalidos' } }];
// minimos aceitos pelos Correios/SuperFrete
W = Math.max(W, 0.3); H = Math.max(Math.ceil(H), 2); Wd = Math.max(Math.ceil(Wd), 11); L = Math.max(Math.ceil(L), 16);
const pkg = { weight: Number(W.toFixed(3)), height: H, width: Wd, length: L };
return [{ json: { valid: true, from_cep: String(sf.origemCep).replace(/\D/g, ''), to_cep, services: servicos, package: pkg } }];

// Filtra servicos com has_error e devolve so o essencial ao browser.
const r = $input.first().json;
const arr = Array.isArray(r.body) ? r.body : (Array.isArray(r) ? r : []);
const servicos = arr.filter(function (s) { return s && s.has_error !== true; }).map(function (s) { return { id: s.id, name: s.name, price: s.price, delivery_time: s.delivery_time }; });
return [{ json: { ok: true, servicos } }];

const OWNER = 'useaura@gmail.com';
const r = $input.first().json;
let ok = false, email = null, localId = null;
if (r && r.statusCode === 200 && r.body && Array.isArray(r.body.users) && r.body.users[0]) {
  const u = r.body.users[0];
  email = u.email || null; localId = u.localId || null;
  if (email === OWNER && localId) ok = true;
}
return [{ json: { ok, email, localId } }];

// FLUXO 3 - monta o body do POST /cart. Le order (SA) + REMETENTE do cofre (secrets/superfrete) + catalogo (config/store).
// NAO emite o token (o HTTP le por expressao). to.document (CPF destinatario) e OBRIGATORIO pela API.
function sv(x) { if (!x) return undefined; if ('stringValue' in x) return x.stringValue; if ('integerValue' in x) return x.integerValue; if ('doubleValue' in x) return x.doubleValue; if ('booleanValue' in x) return x.booleanValue; return undefined; }
function mp(x) { return x && x.mapValue && x.mapValue.fields; }
// token presente?
const tokResp = $('Ler Token Cofre (Etiqueta)').first().json;
let hasToken = false;
if (tokResp && tokResp.statusCode === 200 && tokResp.body && tokResp.body.fields && tokResp.body.fields.token && typeof tokResp.body.fields.token.stringValue === 'string' && tokResp.body.fields.token.stringValue.length > 0) hasToken = true;
if (!hasToken) return [{ json: { valid: false, code: 400, motivo: 'sem token' } }];
// remetente do COFRE (secrets/superfrete, campo remetente = stringValue JSON gravado pelo Fluxo 1)
let rem = null;
try { const rf = tokResp && tokResp.body && tokResp.body.fields && tokResp.body.fields.remetente; if (rf && typeof rf.stringValue === 'string') rem = JSON.parse(rf.stringValue); } catch (e) { rem = null; }
if (!rem || typeof rem !== 'object') return [{ json: { valid: false, code: 400, motivo: 'remetente nao configurado' } }];
const remOut = { name: String(rem.name || rem.nome || ''), document: String(rem.document || rem.cpf || '').replace(/\D/g, ''), address: String(rem.address || rem.endereco || ''), number: String(rem.number || rem.numero || ''), district: String(rem.district || rem.bairro || ''), city: String(rem.city || rem.cidade || ''), state_abbr: String(rem.state_abbr || rem.uf || ''), postal_code: String(rem.postal_code || rem.cep || '').replace(/\D/g, ''), complement: String(rem.complement || rem.complemento || '') };
if (!remOut.document || !remOut.postal_code) return [{ json: { valid: false, code: 400, motivo: 'remetente nao configurado' } }];
// order
const oResp = $('Ler Order (Etiqueta)').first().json;
if (!(oResp && oResp.statusCode === 200 && oResp.body && oResp.body.fields)) return [{ json: { valid: false, code: 404, motivo: 'pedido nao encontrado' } }];
const f = oResp.body.fields;
// GUARDA (frete gratis/local): sem frete_servico nao ha servico de transportadora -> NAO emite etiqueta nem debita saldo (espelho da regra do checkout; cinto de seguranca do caixa mesmo com admin.js cacheado).
const _fs = sv(f.frete_servico);
if (_fs == null || String(_fs).trim() === '') return [{ json: { valid: false, code: 400, motivo: 'Pedido de frete gratis/local - sem servico de transportadora; etiqueta nao se aplica.' } }];
const cli = mp(f.cliente) || {};
const ent = mp(f.entrega) || {};
const cpf = String(sv(cli.cpf) || sv(cli.document) || sv(ent.cpf) || sv(cli.documento) || '').replace(/\D/g, '');
if (cpf.length !== 11) return [{ json: { valid: false, code: 422, motivo: 'CPF do destinatario ausente' } }];
// config/store -> catalogo + categorias + servicoPadrao (remetente NAO vem mais daqui, vem do cofre)
const cfgResp = $('Ler Config Store (Etiqueta)').first().json;
let store = null;
if (cfgResp && cfgResp.statusCode === 200 && cfgResp.body && cfgResp.body.fields && cfgResp.body.fields.payload && typeof cfgResp.body.fields.payload.stringValue === 'string') {
  try { store = JSON.parse(cfgResp.body.fields.payload.stringValue); } catch (e) { store = null; }
}
const sf = (store && store.frete && store.frete.superfrete) || {};
const produtos = (store && store.produtos) || [];
const categorias = sf.categorias || {};
const DEFAULT = { weight: 0.3, height: 4, width: 12, length: 17 };
const mapa = {}; for (const p of produtos) mapa[String(p.id)] = p;
// service escolhido (gravado no pedido pelo checkout); default 1 (PAC)
const service = parseInt(sv(f.frete_servico), 10) || parseInt(sf.servicoPadrao, 10) || 1;
// itens do pedido -> products[] + volumes (mesma heuristica do Fluxo 2)
const itensArr = (f.itens && f.itens.arrayValue && Array.isArray(f.itens.arrayValue.values)) ? f.itens.arrayValue.values : [];
const products = [];
let W = 0, H = 0, Wd = 0, L = 0;
for (const el of itensArr) {
  const iff = el && el.mapValue && el.mapValue.fields; if (!iff) continue;
  const id = String(sv(iff.id));
  const qtd = parseInt(sv(iff.qtd), 10) || 1;
  const prod = mapa[id] || {};
  const nome = String(prod.nome || sv(iff.nome) || id);
  const preco = Number(prod.preco) || Number(sv(iff.preco)) || 0;
  products.push({ name: nome, quantity: qtd, unitary_value: preco });
  let pk = prod.frete; if (!pk) { const cat = prod.categoria; pk = (cat && categorias[cat]) ? categorias[cat] : null; } if (!pk) pk = DEFAULT;
  const w = Number(pk.weight) || DEFAULT.weight, h = Number(pk.height) || DEFAULT.height, wd = Number(pk.width) || DEFAULT.width, l = Number(pk.length) || DEFAULT.length;
  W += w * qtd; H += h * qtd; Wd = Math.max(Wd, wd); L = Math.max(L, l);
}
if (products.length === 0) return [{ json: { valid: false, code: 400, motivo: 'pedido sem itens' } }];
W = Math.max(W, 0.3); H = Math.max(Math.ceil(H), 2); Wd = Math.max(Math.ceil(Wd), 11); L = Math.max(Math.ceil(L), 16);
const volumes = { weight: Number(W.toFixed(3)), height: H, width: Wd, length: L };
const precoEstimado = Number(sv(f.frete)) || 0;
const declaredValue = Number(products.reduce(function(s,p){return s+(Number(p.unitary_value)||0)*(Number(p.quantity)||1);},0).toFixed(2)) || 0;
const cartBody = {
  from: { name: remOut.name, document: remOut.document, address: remOut.address, number: remOut.number, district: remOut.district, city: remOut.city, state_abbr: remOut.state_abbr, postal_code: remOut.postal_code, complement: remOut.complement },
  to: { name: String(sv(cli.nome) || sv(cli.name) || ''), document: cpf, address: String(sv(ent.endereco) || sv(ent.address) || ''), number: String(sv(ent.numero) || sv(ent.number) || ''), district: String(sv(ent.bairro) || sv(ent.district) || ''), city: String(sv(ent.cidade) || sv(ent.city) || ''), state_abbr: String(sv(ent.estado) || sv(ent.uf) || sv(ent.state_abbr) || ''), postal_code: String(sv(ent.cep) || '').replace(/\D/g, '') },
  platform: 'USE AURA',
  service: service,
  products: products,
  volumes: volumes,
  options: { insurance_value: declaredValue, receipt: false, own_hand: false, non_commercial: true }
};
return [{ json: { valid: true, cartBody, precoEstimado } }];

// Guard de saldo: se balance < preco estimado do frete, nao tenta gerar etiqueta.
const r = $input.first().json;
const body = r.body || r;
const bal = Number(body && body.balance != null ? body.balance : NaN);
const prev = $('Montar Cart').first().json;
const preco = Number(prev.precoEstimado) || 0;
if (Number.isFinite(bal) && preco > 0 && bal < preco) {
  return [{ json: { ok: false, saldoInsuficiente: true, saldo: bal, motivo: 'saldo insuficiente' } }];
}
return [{ json: { ok: true, saldo: Number.isFinite(bal) ? bal : null } }];

// Extrai o id do carrinho (cart) devolvido pela SuperFrete.
const r = $input.first().json;
const body = r.body || r;
const cartId = body && (body.id || body.order_id || body.orderId) || null;
if (!cartId) return [{ json: { cartId: null, erro: 'cart sem id', raw: body } }];
return [{ json: { cartId: String(cartId) } }];

// Extrai a URL do PDF (contrato de resposta nao 100% garantido - extracao defensiva).
const r = $input.first().json;
const body = r.body != null ? r.body : r;
const cartId = $('Extrair Cart Id').first().json.cartId;
let pdfUrl = null;
if (typeof body === 'string') pdfUrl = body;
else if (body) {
  pdfUrl = body.url || (body[cartId] && body[cartId].url) || body.link || (body.data && body.data.url) || null;
}
let tracking = null;
if (body && typeof body === 'object') {
  tracking = body.tracking || (body[cartId] && body[cartId].tracking) || null;
}
return [{ json: { pdfUrl, tracking } }];
